package dev.arabicgames.phone;
import android.app.*;import android.content.*;import android.graphics.Bitmap;import android.os.*;import android.view.*;import android.widget.*;
/** Native PS5 remains visible while settings open as an internal floating panel. */
public final class NativeVideoActivity extends Activity {
 private final Handler ui=new Handler(Looper.getMainLooper());private AreaCaptionLayer areaLayer;private final java.util.Map<String,Long> areaRevisions=new java.util.HashMap<>();private ImageView video;private TextView status,caption;private Bitmap shown;
 private final Runnable update=new Runnable(){public void run(){if(isFinishing())return;if(Status.translatorUiVisible){Bitmap frame=PhoneVideoPreview.latest;if(frame!=null&&frame!=shown){video.setImageBitmap(frame);shown=frame;}for(org.json.JSONObject area:Status.areaCaptions.values()){String id=area.optString("id");long revision=area.optLong("revision");if(areaRevisions.getOrDefault(id,-1L)<revision){areaRevisions.put(id,revision);areaLayer.apply(area);}}status.setText(Ps5Session.state+"\n"+Status.metrics);caption.setText(Status.arabic);org.json.JSONObject placed=Status.areaCaptions.get("dialogue");caption.setVisibility(Status.arabic.isEmpty()||placed!=null&&!placed.optBoolean("clear")?View.GONE:View.VISIBLE);}ui.postDelayed(this,100);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(Ui.BG);getWindow().setNavigationBarColor(Ui.BG);
  LinearLayout root=Ui.column(this);root.setBackgroundColor(Ui.BG);LinearLayout controls=new LinearLayout(this);controls.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);
  add(controls,"بدء الترجمة",()->startForegroundService(new Intent(this,CaptureService.class).setAction("ps5")));
  add(controls,"إيقاف الترجمة",()->startForegroundService(new Intent(this,CaptureService.class).setAction("ps5-pause")));
  add(controls,"الإعدادات ⋮",()->{PopupMenu menu=new PopupMenu(this,controls);menu.getMenu().add("محرك الترجمة").setOnMenuItemClickListener(x->{LiveTools.open(this,AiSettingsActivity.class);return true;});menu.getMenu().add("مناطق القراءة والبطاقات").setOnMenuItemClickListener(x->{ReadingOptions.show(this);return true;});menu.getMenu().add("التوقيت والسرعة").setOnMenuItemClickListener(x->{LiveTools.open(this,TimingActivity.class);return true;});menu.getMenu().add("السجل والتصحيحات").setOnMenuItemClickListener(x->{LiveTools.open(this,HistoryActivity.class);return true;});menu.getMenu().add("إنهاء جلسة PS5").setOnMenuItemClickListener(x->{stopService(new Intent(this,CaptureService.class));finish();return true;});menu.show();});root.addView(controls);
  FrameLayout player=new FrameLayout(this);video=new ImageView(this);video.setScaleType(ImageView.ScaleType.FIT_CENTER);player.addView(video,new FrameLayout.LayoutParams(-1,-1));areaLayer=new AreaCaptionLayer(this);player.addView(areaLayer,new FrameLayout.LayoutParams(-1,-1));Ui.fitVideoLayer(player,areaLayer);caption=Ui.text(this,"",20);caption.setGravity(Gravity.CENTER);caption.setTextDirection(View.TEXT_DIRECTION_RTL);caption.setBackgroundColor(0xb0000000);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);cp.setMargins(Ui.dp(this,16),0,Ui.dp(this,16),Ui.dp(this,16));player.addView(caption,cp);root.addView(player,new LinearLayout.LayoutParams(-1,0,1));status=Ui.text(this,"بانتظار فيديو PS5…",12);root.addView(status);PhoneInsets.fit(root);setContentView(root);
  PhoneVideoPreview.enabled=true;startForegroundService(new Intent(this,CaptureService.class).setAction("ps5-preview"));ui.post(update);
 }
 private void add(LinearLayout row,String title,Runnable action){Button b=Ui.button(this,row,title,false,action);b.setTextSize(12);b.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));}
 @Override public void onDestroy(){ui.removeCallbacks(update);PhoneVideoPreview.clear();super.onDestroy();}
}
